#!/usr/bin/env python3
"""Apply PRD-1.1 CI inventory authority files.

This script creates the PRD-1.1 authority/inventory layer. It records no
required-check classification, performs no workflow canonicalisation, enforces no
release gate, changes no branch protection, reconciles no OpenAPI artifacts,
deploys nothing, launches no beta/billing/live learner traffic, and implements
no PRD-2 runtime KG work.
"""
from __future__ import annotations

import argparse
from pathlib import Path

FILES = {'.github/workflows/prd101-ci-inventory-authority.yml': "name: PRD-1.1 CI Inventory Authority\n\non:\n  pull_request:\n    paths:\n      - '.github/workflows/prd101-ci-inventory-authority.yml'\n      - 'docs/engineering/prd1_ci_inventory_authority.md'\n      - 'docs/roadmap/production_readiness/**'\n      - 'scripts/production_readiness/*prd101*'\n      - 'scripts/roadmap_reconciliation/*prd101*'\n      - 'tests/unit/roadmap_reconciliation/test_prd101_ci_inventory_authority.py'\n      - 'Makefile'\n  workflow_dispatch:\n\njobs:\n  prd101-authority:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: '3.11'\n      - name: Compile PRD-1.1 scripts\n        run: |\n          python3 -m py_compile             scripts/production_readiness/apply_prd101_ci_inventory_authority.py             scripts/production_readiness/audit_prd101_ci_inventory_authority.py             scripts/roadmap_reconciliation/capture_prd101_ci_inventory_authority_evidence.py             scripts/roadmap_reconciliation/verify_prd101_ci_inventory_authority.py\n      - name: Run focused PRD-1.1 tests\n        run: |\n          PYTHONPATH=. python3 -m pytest -q             tests/unit/roadmap_reconciliation/test_prd101_ci_inventory_authority.py             --no-cov\n      - name: Verify PRD-1.1 authority\n        run: |\n          PYTHONPATH=. python3 scripts/roadmap_reconciliation/verify_prd101_ci_inventory_authority.py --authority-only --json\n", 'docs/engineering/prd1_ci_inventory_authority.md': '# PRD-1.1 CI Inventory Authority\n\nPRD-1.1 captures the baseline that later PRD-1 slices will use to converge CI and release gates.\n\n## Inventory dimensions\n\nThe inventory records:\n\n- GitHub workflow files under `.github/workflows`.\n- Workflow references to `master`, `main`, `release/**`, release events, deployment/promotion language, pytest commands, and OpenAPI artifacts.\n- Makefile targets and CI-related command references.\n- Local documentation/configuration references to branch protection and required checks.\n- Presence of `openapi.json` and `docs/openapi.json`.\n\n## Boundary\n\nPRD-1.1 does not change workflow semantics. It only records the current state so PRD-1.2 can classify checks and PRD-1.3 can canonicalise workflows under explicit authority.\n\nRuntime KG implementation remains reserved for PRD-2.\n', 'docs/roadmap/production_readiness/prd_101_ci_inventory_authority.md': '# PRD-1.1 — CI Inventory Authority\n\n**Stream:** PRD-1 — Required CI and Release Gate Convergence  \n**Status:** Inventory authority slice; evidence capture required for closure  \n**Owner:** Nkgolo Lebelo  \n**Canonical trunk:** `master`\n\n---\n\n## Purpose\n\nPRD-1.1 creates the authoritative CI inventory baseline for PRD-1.\n\nIt inventories workflow files, workflow trigger references, pytest command forms, branch-name references, release/deployment references, OpenAPI artifact references, Makefile CI targets, and branch-protection/required-check documentation references.\n\n---\n\n## Boundary\n\nPRD-1.1 is inventory-only.\n\nIt does not classify required checks, canonicalise workflows, modify CI commands, edit branch protection, enforce release gates, reconcile OpenAPI artifacts, create release tags, deploy, open public beta, permit live learner traffic, launch billing, process live payments, or implement PRD-2 runtime KG work.\n\n---\n\n## Next slice\n\nThe next authorised slice after PRD-1.1 evidence capture is:\n\n`PRD-1.2 — Required Check Classification`\n\nPRD-1.2 will use this inventory to classify checks as required, advisory, stale, legacy, release-only, blocked, or deferred.\n\n---\n\n## Closure condition\n\nBefore evidence capture, the verifier must report `authority_valid: true` and `valid: false`.\n\nAfter evidence capture, the verifier must report `authority_valid: true`, `valid: true`, and `next_authorised_item: PRD-1.2`.\n', 'docs/roadmap/production_readiness/prd1_ci_inventory_authority_plan.md': '# PRD-1.1 CI Inventory Authority Plan\n\n## Goal\n\nCapture an authoritative inventory of CI, workflow, release, branch-name, pytest-command, OpenAPI, Makefile, and branch-protection references before any PRD-1 canonicalisation or required-check enforcement.\n\n## Steps\n\n1. Apply PRD-1.1 authority files from clean `master` after PRD-1.0 closure.\n2. Run `py_compile`, focused PRD-1.1 tests, and the authority verifier.\n3. Commit and merge the authority branch.\n4. From merged `master`, capture PRD-1.1 inventory evidence.\n5. Run the final PRD-1.1 verifier.\n6. Commit and merge the evidence branch.\n7. Treat PRD-1.2 — Required Check Classification as the next authorised slice.\n\n## Non-goals\n\n- No workflow command canonicalisation.\n- No required-check classification or enforcement.\n- No branch protection modification.\n- No release gate enforcement.\n- No OpenAPI artifact reconciliation.\n- No release tag or deployment.\n- No public beta, live learner traffic, billing, or live payment processing.\n- No PRD-2 runtime KG implementation.\n\n## Expected terminal register state\n\n```json\n{\n  "last_recorded_item": "PRD-1.1",\n  "next_authorised_item": "PRD-1.2"\n}\n```\n', 'docs/roadmap/production_readiness/prd1_ci_inventory_authority.schema.md': '# PRD-1.1 CI Inventory Authority Schema\n\nThe PRD-1.1 inventory snapshot is stored at:\n\n`docs/roadmap/production_readiness/prd1_ci_inventory_authority.json`\n\nRequired top-level fields:\n\n| Field | Meaning |\n|---|---|\n| `schema_version` | Must be `prd1-ci-inventory-authority/v1`. |\n| `prd_id` | Must be `PRD-1.1`. |\n| `stream_id` | Must be `PRD-1-CI-RELEASE-GATE-CONVERGENCE`. |\n| `workflow_inventory` | Per-workflow inventory of branch, release, deployment, pytest, and OpenAPI references. |\n| `makefile_inventory` | Makefile target and command-reference inventory. |\n| `openapi_inventory` | Presence and path inventory for OpenAPI artifacts. |\n| `branch_protection_inventory` | Local documentation/configuration references to branch protection and required checks. |\n| `summary` | Count-level summary used by PRD-1.2 classification. |\n| `authority_boundaries` | Explicitly closed release/beta/billing/live/KG boundaries. |\n| `implementation_boundaries` | Explicit no-change status for PRD-1.1. |\n\nPRD-1.1 terminal state requires:\n\n- `last_recorded_item: PRD-1.1`\n- `next_authorised_item: PRD-1.2`\n- `PRD-1.1` sequence entry status `recorded`\n- `PRD-1.2` sequence entry authorised `true`\n- CI inventory evidence recorded\n- no required-check classification performed\n- no workflow canonicalisation performed\n- no release gate enforcement performed\n', 'docs/roadmap/production_readiness/prd_101_ci_inventory_authority_record.json': '{\n  "authority_switch_executed": true,\n  "billing_launch_authorised": false,\n  "branch_protection_modified": false,\n  "ci_inventory_authority_recorded": false,\n  "ci_inventory_evidence_recorded": false,\n  "ci_inventory_performed": false,\n  "ci_inventory_recorded": false,\n  "ci_workflow_changes_performed": false,\n  "deployment_authorised": false,\n  "live_learner_traffic_authorised": false,\n  "live_payment_processing_authorised": false,\n  "new_kg_slice_authorised": false,\n  "next_authorised_item": "PRD-1.1",\n  "no_branch_protection_change_performed": true,\n  "no_ci_workflow_changes_performed": true,\n  "no_openapi_reconciliation_performed": true,\n  "no_prd2_implementation_performed": true,\n  "no_release_gate_enforcement_performed": true,\n  "no_required_check_classification_performed": true,\n  "no_required_check_enforcement_performed": true,\n  "no_workflow_canonicalisation_performed": true,\n  "openapi_reconciliation_performed": false,\n  "prd100_ci_release_gate_stream_authority_valid": null,\n  "prd1_2_authorised": false,\n  "prd2_implementation_authorised": false,\n  "prd_id": "PRD-1.1",\n  "production_release_authorised": false,\n  "public_beta_authorised": false,\n  "public_beta_live_traffic_authorised": false,\n  "release_gate_enforced": false,\n  "release_tag_authorised": false,\n  "required_check_classification_performed": false,\n  "required_checks_enforced": false,\n  "runtime_kg_authority_switch_authorised": true,\n  "runtime_kg_implementation_claimed": true,\n  "schema_version": "prd1-ci-inventory-authority-record/v1",\n  "status": "authority_defined_evidence_pending",\n  "stream_id": "PRD-1-CI-RELEASE-GATE-CONVERGENCE",\n  "workflow_canonicalisation_performed": false\n}\n', 'scripts/production_readiness/audit_prd101_ci_inventory_authority.py': '#!/usr/bin/env python3\n"""Audit PRD-1.1 CI inventory authority."""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport re\nfrom pathlib import Path\nfrom typing import Any\n\nfrom scripts.roadmap_reconciliation.verify_prd100_ci_release_gate_stream_authority import evaluate as evaluate_prd100\n\nPRD_ID = "PRD-1.1"\nSTREAM_ID = "PRD-1-CI-RELEASE-GATE-CONVERGENCE"\nROOT = Path("docs/roadmap/production_readiness")\nREGISTER = ROOT / "production_readiness_register.json"\nPRD1_REGISTER = ROOT / "prd1_ci_release_gate_register.json"\nPRD_DOC = ROOT / "prd_101_ci_inventory_authority.md"\nPLAN = ROOT / "prd1_ci_inventory_authority_plan.md"\nSCHEMA_DOC = ROOT / "prd1_ci_inventory_authority.schema.md"\nRECORD = ROOT / "prd_101_ci_inventory_authority_record.json"\nSNAPSHOT = ROOT / "prd1_ci_inventory_authority.json"\nENGINEERING_DOC = Path("docs/engineering/prd1_ci_inventory_authority.md")\n\nTRUE_KEYS = ["runtime_kg_implementation_claimed", "runtime_kg_authority_switch_authorised", "authority_switch_executed"]\nFALSE_KEYS = [\n    "production_release_authorised",\n    "deployment_authorised",\n    "release_tag_authorised",\n    "public_beta_authorised",\n    "public_beta_live_traffic_authorised",\n    "live_learner_traffic_authorised",\n    "billing_launch_authorised",\n    "live_payment_processing_authorised",\n    "new_kg_slice_authorised",\n    "prd2_implementation_authorised",\n]\nNO_CHANGE_KEYS = [\n    "ci_workflow_changes_performed",\n    "required_checks_enforced",\n    "release_gate_enforced",\n    "branch_protection_modified",\n    "workflow_canonicalisation_performed",\n    "openapi_reconciliation_performed",\n    "required_check_classification_performed",\n]\n\nWORKFLOW_SUFFIXES = {".yml", ".yaml"}\nCI_TERMS = ["pytest", "coverage", "py_compile", "ruff", "mypy", "playwright", "docker", "openapi", "alembic"]\nDEPLOYMENT_TERMS = ["deploy", "deployment", "promotion", "production", "environment", "release"]\nBRANCH_PROTECTION_TERMS = ["branch protection", "required check", "required_checks", "required status", "status check"]\n\n\ndef read_json(path: Path) -> dict[str, Any]:\n    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}\n\n\ndef read_text(path: Path) -> str:\n    return path.read_text(encoding="utf-8", errors="replace") if path.exists() else ""\n\n\ndef bool_find(pattern: str, text: str) -> bool:\n    return re.search(pattern, text, flags=re.IGNORECASE | re.MULTILINE) is not None\n\n\ndef workflow_inventory(root: Path) -> list[dict[str, Any]]:\n    workflow_root = root / ".github" / "workflows"\n    items: list[dict[str, Any]] = []\n    if not workflow_root.exists():\n        return items\n    for path in sorted(p for p in workflow_root.iterdir() if p.is_file() and p.suffix in WORKFLOW_SUFFIXES):\n        text = read_text(path)\n        lower = text.lower()\n        items.append({\n            "path": path.as_posix(),\n            "line_count": len(text.splitlines()),\n            "mentions_master": "master" in lower,\n            "mentions_main": bool_find(r"(^|[^a-z0-9_-])main([^a-z0-9_-]|$)", text),\n            "mentions_release_branch": "release/" in lower or "release/**" in lower,\n            "mentions_release_event": bool_find(r"on:\\s*release|types:\\s*\\[[^\\]]*published|release:", text),\n            "mentions_deployment_or_promotion": any(term in lower for term in DEPLOYMENT_TERMS),\n            "mentions_openapi": "openapi" in lower,\n            "mentions_pytest": "pytest" in lower,\n            "uses_python_m_pytest": "python -m pytest" in lower,\n            "uses_python3_m_pytest": "python3 -m pytest" in lower,\n            "ci_terms": sorted(term for term in CI_TERMS if term in lower),\n        })\n    return items\n\n\ndef makefile_inventory(root: Path) -> dict[str, Any]:\n    path = root / "Makefile"\n    text = read_text(path)\n    targets: list[str] = []\n    for line in text.splitlines():\n        if line and not line.startswith(("\\t", " ", "#")) and ":" in line:\n            name = line.split(":", 1)[0].strip()\n            if name and not name.startswith("."):\n                targets.append(name)\n    lower = text.lower()\n    return {\n        "path": "Makefile",\n        "exists": path.exists(),\n        "target_count": len(targets),\n        "ci_like_target_count": sum(1 for target in targets if any(term in target.lower() for term in ["test", "pytest", "ci", "check", "verify", "prd"])),\n        "targets_sample": targets[:75],\n        "mentions_pytest": "pytest" in lower,\n        "uses_python_m_pytest": "python -m pytest" in lower,\n        "uses_python3_m_pytest": "python3 -m pytest" in lower,\n        "mentions_openapi": "openapi" in lower,\n    }\n\n\ndef openapi_inventory(root: Path) -> dict[str, Any]:\n    paths = [Path("openapi.json"), Path("docs/openapi.json")]\n    return {\n        "paths": [\n            {"path": path.as_posix(), "exists": (root / path).exists(), "size_bytes": (root / path).stat().st_size if (root / path).exists() else None}\n            for path in paths\n        ],\n        "root_openapi_present": (root / "openapi.json").exists(),\n        "docs_openapi_present": (root / "docs" / "openapi.json").exists(),\n    }\n\n\ndef branch_protection_inventory(root: Path) -> dict[str, Any]:\n    refs: list[dict[str, Any]] = []\n    search_roots = [root / "docs", root / ".github"]\n    for base in search_roots:\n        if not base.exists():\n            continue\n        for path in sorted(p for p in base.rglob("*") if p.is_file() and p.suffix.lower() in {".md", ".json", ".yml", ".yaml"}):\n            rel = path.relative_to(root).as_posix()\n            text = read_text(path)\n            lower = text.lower()\n            matched = sorted(term for term in BRANCH_PROTECTION_TERMS if term in lower)\n            if matched:\n                refs.append({"path": rel, "matched_terms": matched})\n    return {"reference_count": len(refs), "references": refs[:100]}\n\n\ndef collect_ci_inventory(root: Path = Path("."), captured_at: str | None = None) -> dict[str, Any]:\n    workflows = workflow_inventory(root)\n    makefile = makefile_inventory(root)\n    openapi = openapi_inventory(root)\n    branch_protection = branch_protection_inventory(root)\n    summary = {\n        "workflow_count": len(workflows),\n        "master_workflow_count": sum(1 for item in workflows if item["mentions_master"]),\n        "main_workflow_count": sum(1 for item in workflows if item["mentions_main"]),\n        "release_branch_workflow_count": sum(1 for item in workflows if item["mentions_release_branch"]),\n        "release_event_workflow_count": sum(1 for item in workflows if item["mentions_release_event"]),\n        "deployment_reference_workflow_count": sum(1 for item in workflows if item["mentions_deployment_or_promotion"]),\n        "openapi_reference_workflow_count": sum(1 for item in workflows if item["mentions_openapi"]),\n        "pytest_reference_workflow_count": sum(1 for item in workflows if item["mentions_pytest"]),\n        "python_m_pytest_workflow_count": sum(1 for item in workflows if item["uses_python_m_pytest"]),\n        "python3_m_pytest_workflow_count": sum(1 for item in workflows if item["uses_python3_m_pytest"]),\n        "makefile_ci_like_target_count": makefile["ci_like_target_count"],\n        "branch_protection_reference_count": branch_protection["reference_count"],\n        "root_openapi_present": openapi["root_openapi_present"],\n        "docs_openapi_present": openapi["docs_openapi_present"],\n    }\n    return {\n        "schema_version": "prd1-ci-inventory-authority/v1",\n        "prd_id": PRD_ID,\n        "stream_id": STREAM_ID,\n        "captured_at": captured_at,\n        "workflow_inventory": workflows,\n        "makefile_inventory": makefile,\n        "openapi_inventory": openapi,\n        "branch_protection_inventory": branch_protection,\n        "summary": summary,\n        "authority_boundaries": {**{key: True for key in TRUE_KEYS}, **{key: False for key in FALSE_KEYS}},\n        "implementation_boundaries": {key: False for key in NO_CHANGE_KEYS},\n        "next_authorised_item": "PRD-1.2",\n    }\n\n\ndef prd1_1_recorded(prd1_register: dict[str, Any]) -> bool:\n    if prd1_register.get("last_recorded_item") != PRD_ID:\n        return False\n    if prd1_register.get("next_authorised_item") != "PRD-1.2":\n        return False\n    for item in prd1_register.get("prd1_sequence", []):\n        if item.get("prd_id") == PRD_ID and not (item.get("authorised") is True and item.get("status") == "recorded"):\n            return False\n        if item.get("prd_id") == "PRD-1.2" and not (item.get("authorised") is True and item.get("status") in {"authorised", "next_authorised"}):\n            return False\n    return True\n\n\ndef production_register_position(register: dict[str, Any]) -> str:\n    last_item = register.get("last_recorded_item")\n    next_item = register.get("next_authorised_item")\n    if last_item == "PRD-1.0" and next_item == PRD_ID:\n        return "after_prd1_0_before_prd1_1_capture"\n    if last_item == PRD_ID and next_item == "PRD-1.2":\n        return "prd1_1_recorded"\n    return "unexpected"\n\n\ndef inventory_snapshot(root: Path, captured_at: str | None = None) -> dict[str, Any]:\n    register = read_json(root / REGISTER)\n    prd1_register = read_json(root / PRD1_REGISTER)\n    inventory = collect_ci_inventory(root, captured_at=captured_at)\n    inventory["production_readiness_register_summary"] = {\n        "last_recorded_item": register.get("last_recorded_item"),\n        "next_authorised_item": register.get("next_authorised_item"),\n        "position": production_register_position(register),\n    }\n    inventory["prd1_register_summary"] = {\n        "last_recorded_item": prd1_register.get("last_recorded_item"),\n        "next_authorised_item": prd1_register.get("next_authorised_item"),\n        "prd1_1_recorded": prd1_1_recorded(prd1_register),\n    }\n    return inventory\n\n\ndef audit(root: Path = Path(".")) -> dict[str, Any]:\n    errors: list[str] = []\n    warnings: list[str] = []\n    register = read_json(root / REGISTER)\n    prd1_register = read_json(root / PRD1_REGISTER)\n    record = read_json(root / RECORD)\n    saved_snapshot = read_json(root / SNAPSHOT)\n    live_snapshot = inventory_snapshot(root)\n    prd100 = evaluate_prd100(root)\n\n    for path in [PRD_DOC, PLAN, SCHEMA_DOC, RECORD, ENGINEERING_DOC]:\n        if not (root / path).exists():\n            errors.append(f"missing required PRD-1.1 file: {path}")\n\n    if prd100.get("valid") is not True:\n        errors.append("PRD-1.0 verifier must remain valid before PRD-1.1")\n    if production_register_position(register) == "unexpected":\n        errors.append("production readiness register must be positioned at PRD-1.0/PRD-1.1 or PRD-1.1/PRD-1.2")\n    if prd1_register.get("schema_version") != "prd1-ci-release-gate-register/v1":\n        errors.append("PRD-1 register schema_version must remain prd1-ci-release-gate-register/v1")\n    if prd1_register.get("stream_id") != STREAM_ID:\n        errors.append("PRD-1 register stream_id must remain canonical")\n\n    required_text = [\n        (read_text(root / PRD_DOC), "inventory-only", "PRD-1.1 doc must preserve inventory-only boundary"),\n        (read_text(root / PRD_DOC), "PRD-1.2 — Required Check Classification", "PRD-1.1 doc must identify PRD-1.2 as next slice"),\n        (read_text(root / PLAN), "last_recorded_item", "PRD-1.1 plan must describe terminal register state"),\n        (read_text(root / SCHEMA_DOC), "prd1-ci-inventory-authority/v1", "PRD-1.1 schema must define inventory version"),\n        (read_text(root / ENGINEERING_DOC), "Runtime KG implementation remains reserved for PRD-2", "engineering doc must preserve PRD-2 boundary"),\n    ]\n    for text, phrase, message in required_text:\n        if phrase not in text:\n            errors.append(message)\n\n    for key in TRUE_KEYS:\n        if record.get(key) is not True:\n            errors.append(f"{key} must remain true")\n    for key in FALSE_KEYS:\n        if record.get(key) is not False:\n            errors.append(f"{key} must remain false")\n    for key in NO_CHANGE_KEYS:\n        if record.get(key) is not False:\n            errors.append(f"{key} must remain false in PRD-1.1")\n\n    for key in [\n        "no_required_check_classification_performed",\n        "no_workflow_canonicalisation_performed",\n        "no_ci_workflow_changes_performed",\n        "no_required_check_enforcement_performed",\n        "no_release_gate_enforcement_performed",\n        "no_branch_protection_change_performed",\n        "no_openapi_reconciliation_performed",\n        "no_prd2_implementation_performed",\n    ]:\n        if record.get(key) is not True:\n            errors.append(f"{key} must be true")\n\n    if live_snapshot.get("summary", {}).get("workflow_count", 0) <= 0:\n        errors.append("CI inventory must include at least one workflow")\n    if "makefile_inventory" not in live_snapshot:\n        errors.append("CI inventory must include Makefile inventory")\n    if "openapi_inventory" not in live_snapshot:\n        errors.append("CI inventory must include OpenAPI inventory")\n\n    authority_valid = not errors\n    recorded = record.get("ci_inventory_authority_recorded") is True and record.get("ci_inventory_evidence_recorded") is True\n    snapshot_recorded = (\n        saved_snapshot.get("schema_version") == "prd1-ci-inventory-authority/v1"\n        and saved_snapshot.get("prd_id") == PRD_ID\n        and saved_snapshot.get("summary", {}).get("workflow_count", 0) > 0\n    )\n    inventory_count_matches = (\n        snapshot_recorded\n        and saved_snapshot.get("summary", {}).get("workflow_count") == live_snapshot.get("summary", {}).get("workflow_count")\n    )\n    final_valid = (\n        authority_valid\n        and recorded\n        and snapshot_recorded\n        and inventory_count_matches\n        and prd1_1_recorded(prd1_register)\n        and register.get("last_recorded_item") == PRD_ID\n        and register.get("next_authorised_item") == "PRD-1.2"\n        and record.get("next_authorised_item") == "PRD-1.2"\n        and record.get("prd1_2_authorised") is True\n        and record.get("ci_inventory_performed") is True\n    )\n    if authority_valid and not final_valid:\n        warnings.append("PRD-1.1 authority is valid but evidence capture has not completed")\n\n    return {\n        "valid": final_valid,\n        "authority_valid": authority_valid,\n        "prd_id": PRD_ID,\n        "stream_id": STREAM_ID,\n        "errors": errors,\n        "warnings": warnings,\n        "prd100_ci_release_gate_stream_authority_valid": prd100.get("valid") is True,\n        "ci_inventory_authority_recorded": record.get("ci_inventory_authority_recorded") is True,\n        "ci_inventory_evidence_recorded": record.get("ci_inventory_evidence_recorded") is True,\n        "ci_inventory_recorded": record.get("ci_inventory_recorded") is True,\n        "ci_inventory_performed": record.get("ci_inventory_performed") is True,\n        "snapshot_recorded": snapshot_recorded,\n        "inventory_count_matches": inventory_count_matches,\n        "workflow_count": live_snapshot.get("summary", {}).get("workflow_count"),\n        "master_workflow_count": live_snapshot.get("summary", {}).get("master_workflow_count"),\n        "main_workflow_count": live_snapshot.get("summary", {}).get("main_workflow_count"),\n        "release_branch_workflow_count": live_snapshot.get("summary", {}).get("release_branch_workflow_count"),\n        "release_event_workflow_count": live_snapshot.get("summary", {}).get("release_event_workflow_count"),\n        "deployment_reference_workflow_count": live_snapshot.get("summary", {}).get("deployment_reference_workflow_count"),\n        "openapi_reference_workflow_count": live_snapshot.get("summary", {}).get("openapi_reference_workflow_count"),\n        "pytest_reference_workflow_count": live_snapshot.get("summary", {}).get("pytest_reference_workflow_count"),\n        "python_m_pytest_workflow_count": live_snapshot.get("summary", {}).get("python_m_pytest_workflow_count"),\n        "python3_m_pytest_workflow_count": live_snapshot.get("summary", {}).get("python3_m_pytest_workflow_count"),\n        "makefile_ci_like_target_count": live_snapshot.get("summary", {}).get("makefile_ci_like_target_count"),\n        "branch_protection_reference_count": live_snapshot.get("summary", {}).get("branch_protection_reference_count"),\n        "root_openapi_present": live_snapshot.get("summary", {}).get("root_openapi_present"),\n        "docs_openapi_present": live_snapshot.get("summary", {}).get("docs_openapi_present"),\n        "next_authorised_item": record.get("next_authorised_item"),\n        "register_next_authorised_item": register.get("next_authorised_item"),\n        "production_register_position": production_register_position(register),\n        "prd1_2_authorised": record.get("prd1_2_authorised") is True,\n        "no_required_check_classification_performed": record.get("no_required_check_classification_performed") is True,\n        "no_workflow_canonicalisation_performed": record.get("no_workflow_canonicalisation_performed") is True,\n        "no_ci_workflow_changes_performed": record.get("no_ci_workflow_changes_performed") is True,\n        "no_required_check_enforcement_performed": record.get("no_required_check_enforcement_performed") is True,\n        "no_release_gate_enforcement_performed": record.get("no_release_gate_enforcement_performed") is True,\n        "no_branch_protection_change_performed": record.get("no_branch_protection_change_performed") is True,\n        "no_openapi_reconciliation_performed": record.get("no_openapi_reconciliation_performed") is True,\n        "no_prd2_implementation_performed": record.get("no_prd2_implementation_performed") is True,\n        **{key: record.get(key) is True for key in TRUE_KEYS},\n        **{key: record.get(key) is True for key in FALSE_KEYS},\n        **{key: record.get(key) is True for key in NO_CHANGE_KEYS},\n    }\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--json", action="store_true")\n    parser.add_argument("--root", default=".")\n    args = parser.parse_args()\n    result = audit(Path(args.root))\n    if args.json:\n        print(json.dumps(result, indent=2, sort_keys=True))\n    else:\n        print(f"PRD-1.1 valid: {result[\'valid\']}")\n        print(f"PRD-1.1 authority_valid: {result[\'authority_valid\']}")\n        for error in result["errors"]:\n            print(f"ERROR: {error}")\n        for warning in result["warnings"]:\n            print(f"WARNING: {warning}")\n    return 0 if result["valid"] else 1\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n', 'scripts/roadmap_reconciliation/verify_prd101_ci_inventory_authority.py': '#!/usr/bin/env python3\n"""Verify PRD-1.1 CI inventory authority."""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nfrom pathlib import Path\nfrom typing import Any\n\nfrom scripts.production_readiness.audit_prd101_ci_inventory_authority import audit\n\n\ndef evaluate(root: Path = Path(".")) -> dict[str, Any]:\n    return audit(root)\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--authority-only", action="store_true")\n    parser.add_argument("--json", action="store_true")\n    parser.add_argument("--root", default=".")\n    args = parser.parse_args()\n    result = evaluate(Path(args.root))\n    if args.json:\n        print(json.dumps(result, indent=2, sort_keys=True))\n    else:\n        print(f"PRD-1.1 valid: {result[\'valid\']}")\n        print(f"PRD-1.1 authority_valid: {result[\'authority_valid\']}")\n        for error in result["errors"]:\n            print(f"ERROR: {error}")\n        for warning in result["warnings"]:\n            print(f"WARNING: {warning}")\n    return 0 if (result["authority_valid"] if args.authority_only else result["valid"]) else 1\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n', 'scripts/roadmap_reconciliation/capture_prd101_ci_inventory_authority_evidence.py': '#!/usr/bin/env python3\n"""Capture PRD-1.1 CI inventory authority evidence."""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport subprocess\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nfrom scripts.production_readiness.apply_prd101_ci_inventory_authority import apply as apply_authority\nfrom scripts.production_readiness.audit_prd101_ci_inventory_authority import (\n    FALSE_KEYS,\n    NO_CHANGE_KEYS,\n    PRD_ID,\n    PRD1_REGISTER,\n    RECORD,\n    REGISTER,\n    SNAPSHOT,\n    STREAM_ID,\n    TRUE_KEYS,\n    inventory_snapshot,\n)\nfrom scripts.roadmap_reconciliation.verify_prd101_ci_inventory_authority import evaluate\n\nEVIDENCE_DIR = Path("docs/release-evidence/production-readiness/prd-101-ci-inventory-authority")\n\n\ndef read_json(path: Path) -> dict:\n    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}\n\n\ndef write_json(path: Path, data: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, sort_keys=True) + "\\n", encoding="utf-8")\n\n\ndef git_state(target_branch: str) -> dict:\n    def run(args: list[str]) -> str | None:\n        try:\n            return subprocess.check_output(args, text=True, stderr=subprocess.DEVNULL).strip()\n        except (subprocess.CalledProcessError, FileNotFoundError):\n            return None\n    status = run(["git", "status", "--short"])\n    return {\n        "branch": run(["git", "branch", "--show-current"]),\n        "head_sha": run(["git", "rev-parse", "HEAD"]),\n        "status_short": status,\n        "target_branch": target_branch,\n        "git_available": status is not None,\n    }\n\n\ndef update_prd1_register(now: str) -> dict:\n    data = read_json(PRD1_REGISTER)\n    data["last_recorded_item"] = PRD_ID\n    data["next_authorised_item"] = "PRD-1.2"\n    data["last_recorded_at"] = now\n    data["status"] = "prd1_1_ci_inventory_recorded_prd1_2_authorised"\n    data["ci_inventory_authority_recorded_at"] = now\n    data["ci_inventory_authority_recorded"] = True\n    for item in data.get("prd1_sequence", []):\n        if item.get("prd_id") == "PRD-1.0":\n            item["authorised"] = True\n            item["status"] = "recorded"\n        elif item.get("prd_id") == PRD_ID:\n            item["authorised"] = True\n            item["status"] = "recorded"\n        elif item.get("prd_id") == "PRD-1.2":\n            item["authorised"] = True\n            item["status"] = "authorised"\n        elif item.get("prd_id") not in {"PRD-1.0", PRD_ID, "PRD-1.2"}:\n            item.setdefault("authorised", False)\n            item.setdefault("status", "blocked")\n    data.setdefault("authority_boundaries", {})\n    for key in TRUE_KEYS:\n        data["authority_boundaries"][key] = True\n    for key in FALSE_KEYS:\n        data["authority_boundaries"][key] = False\n    data.setdefault("implementation_boundaries", {})\n    for key in NO_CHANGE_KEYS:\n        data["implementation_boundaries"][key] = False\n    data["implementation_boundaries"]["ci_inventory_performed"] = True\n    write_json(PRD1_REGISTER, data)\n    return data\n\n\ndef update_production_register(now: str, prd1_register: dict) -> dict:\n    register = read_json(REGISTER)\n    register["last_recorded_item"] = PRD_ID\n    register["last_recorded_at"] = now\n    register["next_authorised_item"] = "PRD-1.2"\n    register["status"] = "prd_1_1_ci_inventory_recorded_prd_1_2_authorised"\n    register["prd1_next_authorised_item"] = "PRD-1.2"\n    register["prd1_ci_inventory_authority_recorded"] = True\n    register["prd1_ci_inventory_authority_recorded_at"] = now\n    register["prd1_sequence"] = prd1_register.get("prd1_sequence", [])\n    register.setdefault("current_truth", {})["prd1_ci_inventory_authority_recorded"] = True\n    register["current_truth"]["prd1_next_authorised_item"] = "PRD-1.2"\n    for item in register.get("production_readiness_sequence", []):\n        if item.get("prd_id") == "PRD-1":\n            item["authorised"] = True\n            item["status"] = "in_progress"\n        elif item.get("prd_id") != "PRD-1":\n            item.setdefault("authorised", False)\n            item.setdefault("status", "blocked")\n    register.setdefault("authority_boundaries", {})\n    for key in TRUE_KEYS:\n        register["authority_boundaries"][key] = True\n    register["authority_boundaries"]["prd1_implementation_authorised"] = False\n    for key in FALSE_KEYS:\n        register["authority_boundaries"][key] = False\n    write_json(REGISTER, register)\n    return register\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--claim-prd101-ci-inventory-authority", action="store_true")\n    parser.add_argument("--prd-owner", required=True)\n    parser.add_argument("--target-branch", default="master")\n    parser.add_argument("--require-valid", action="store_true")\n    parser.add_argument("--json", action="store_true")\n    args = parser.parse_args()\n    if not args.claim_prd101_ci_inventory_authority:\n        raise SystemExit("must pass --claim-prd101-ci-inventory-authority")\n\n    before = evaluate(Path("."))\n    if not before.get("authority_valid"):\n        raise SystemExit(json.dumps(before, indent=2, sort_keys=True))\n\n    now = datetime.now(timezone.utc).isoformat()\n    state = git_state(args.target_branch)\n    apply_authority(Path("."), write_files=True)\n    snapshot = inventory_snapshot(Path("."), captured_at=now)\n    write_json(SNAPSHOT, snapshot)\n    prd1_register = update_prd1_register(now)\n    production_register = update_production_register(now, prd1_register)\n    snapshot = inventory_snapshot(Path("."), captured_at=now)\n    write_json(SNAPSHOT, snapshot)\n\n    record = read_json(RECORD)\n    record.update({\n        "prd_id": PRD_ID,\n        "stream_id": STREAM_ID,\n        "status": "prd1_1_ci_inventory_recorded_prd1_2_authorised",\n        "prd100_ci_release_gate_stream_authority_valid": before.get("prd100_ci_release_gate_stream_authority_valid") is True,\n        "ci_inventory_authority_recorded": True,\n        "ci_inventory_evidence_recorded": True,\n        "ci_inventory_recorded": True,\n        "ci_inventory_performed": True,\n        "next_authorised_item": "PRD-1.2",\n        "prd1_2_authorised": True,\n        "required_check_classification_performed": False,\n        "workflow_canonicalisation_performed": False,\n        "ci_workflow_changes_performed": False,\n        "required_checks_enforced": False,\n        "release_gate_enforced": False,\n        "branch_protection_modified": False,\n        "openapi_reconciliation_performed": False,\n        "no_required_check_classification_performed": True,\n        "no_workflow_canonicalisation_performed": True,\n        "no_ci_workflow_changes_performed": True,\n        "no_required_check_enforcement_performed": True,\n        "no_release_gate_enforcement_performed": True,\n        "no_branch_protection_change_performed": True,\n        "no_openapi_reconciliation_performed": True,\n        "no_prd2_implementation_performed": True,\n        "inventory_summary": snapshot.get("summary", {}),\n        "evidence_owner": args.prd_owner,\n        "evidence_captured_at": now,\n        "target_branch": args.target_branch,\n        "clean_git_state_at_capture": state["status_short"] == "" if state.get("git_available") else None,\n        "git_state": state,\n    })\n    for key in TRUE_KEYS:\n        record[key] = True\n    for key in FALSE_KEYS:\n        record[key] = False\n    for key in NO_CHANGE_KEYS:\n        record[key] = False\n    write_json(RECORD, record)\n\n    after = evaluate(Path("."))\n    record["verification"] = after\n    write_json(RECORD, record)\n\n    EVIDENCE_DIR.mkdir(parents=True, exist_ok=True)\n    write_json(EVIDENCE_DIR / "verification.json", after)\n    write_json(EVIDENCE_DIR / "git_state.json", state)\n    write_json(EVIDENCE_DIR / "production_readiness_register_prd1_1_snapshot.json", production_register)\n    write_json(EVIDENCE_DIR / "prd1_ci_release_gate_register_snapshot.json", prd1_register)\n    write_json(EVIDENCE_DIR / "prd1_ci_inventory_authority_snapshot.json", snapshot)\n    (EVIDENCE_DIR / "evidence_index.md").write_text(\n        "# PRD-1.1 CI Inventory Authority Evidence\\n\\n"\n        f"- Captured at: {now}\\n"\n        f"- Evidence owner: {args.prd_owner}\\n"\n        f"- Target branch: {args.target_branch}\\n"\n        f"- Valid: {after.get(\'valid\')}\\n"\n        f"- Authority valid: {after.get(\'authority_valid\')}\\n"\n        f"- PRD-1.0 valid: {after.get(\'prd100_ci_release_gate_stream_authority_valid\')}\\n"\n        f"- Workflow count: {after.get(\'workflow_count\')}\\n"\n        f"- master workflow references: {after.get(\'master_workflow_count\')}\\n"\n        f"- main workflow references: {after.get(\'main_workflow_count\')}\\n"\n        f"- release-branch workflow references: {after.get(\'release_branch_workflow_count\')}\\n"\n        f"- release-event workflow references: {after.get(\'release_event_workflow_count\')}\\n"\n        f"- deployment/promotion workflow references: {after.get(\'deployment_reference_workflow_count\')}\\n"\n        f"- OpenAPI workflow references: {after.get(\'openapi_reference_workflow_count\')}\\n"\n        f"- pytest workflow references: {after.get(\'pytest_reference_workflow_count\')}\\n"\n        f"- Next authorised item: {after.get(\'register_next_authorised_item\')}\\n"\n        "- Required-check classification performed by PRD-1.1: false\\n"\n        "- Workflow canonicalisation performed by PRD-1.1: false\\n"\n        "- CI workflow changes performed by PRD-1.1: false\\n"\n        "- Release gate enforcement performed by PRD-1.1: false\\n"\n        "- PRD-2 implementation performed by PRD-1.1: false\\n"\n        "- Production release/deployment/beta/billing/live learner traffic/new KG scope: false\\n",\n        encoding="utf-8",\n    )\n\n    if args.require_valid and not after.get("valid"):\n        raise SystemExit(json.dumps(after, indent=2, sort_keys=True))\n    if args.json:\n        print(json.dumps(after, indent=2, sort_keys=True))\n    else:\n        print(f"PRD-1.1 evidence valid: {after.get(\'valid\')}")\n    return 0 if after.get("valid") else 1\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n', 'tests/unit/roadmap_reconciliation/test_prd101_ci_inventory_authority.py': 'from __future__ import annotations\n\nfrom pathlib import Path\n\nimport pytest\n\nfrom scripts.production_readiness.audit_prd101_ci_inventory_authority import collect_ci_inventory, inventory_snapshot\nfrom scripts.roadmap_reconciliation.verify_prd101_ci_inventory_authority import evaluate\n\nROOT = Path(__file__).resolve().parents[3]\n\n\n@pytest.fixture(scope="module")\ndef prd101_result() -> dict:\n    return evaluate(ROOT)\n\n\ndef test_prd101_authority_valid_after_apply(prd101_result: dict) -> None:\n    assert prd101_result["authority_valid"] is True\n    assert prd101_result["prd100_ci_release_gate_stream_authority_valid"] is True\n    assert prd101_result["workflow_count"] > 0\n\n\ndef test_prd101_inventory_collects_core_dimensions() -> None:\n    inventory = collect_ci_inventory(ROOT)\n    assert inventory["schema_version"] == "prd1-ci-inventory-authority/v1"\n    assert inventory["prd_id"] == "PRD-1.1"\n    assert inventory["summary"]["workflow_count"] > 0\n    assert "makefile_inventory" in inventory\n    assert "openapi_inventory" in inventory\n    assert "branch_protection_inventory" in inventory\n\n\ndef test_prd101_keeps_classification_canonicalisation_and_release_gates_closed(prd101_result: dict) -> None:\n    assert prd101_result["no_required_check_classification_performed"] is True\n    assert prd101_result["no_workflow_canonicalisation_performed"] is True\n    assert prd101_result["no_ci_workflow_changes_performed"] is True\n    assert prd101_result["no_required_check_enforcement_performed"] is True\n    assert prd101_result["no_release_gate_enforcement_performed"] is True\n    assert prd101_result["no_branch_protection_change_performed"] is True\n    assert prd101_result["no_openapi_reconciliation_performed"] is True\n    assert prd101_result["no_prd2_implementation_performed"] is True\n\n\ndef test_prd101_keeps_release_live_and_prd2_boundaries_closed(prd101_result: dict) -> None:\n    assert prd101_result["production_release_authorised"] is False\n    assert prd101_result["deployment_authorised"] is False\n    assert prd101_result["release_tag_authorised"] is False\n    assert prd101_result["public_beta_authorised"] is False\n    assert prd101_result["live_learner_traffic_authorised"] is False\n    assert prd101_result["billing_launch_authorised"] is False\n    assert prd101_result["live_payment_processing_authorised"] is False\n    assert prd101_result["new_kg_slice_authorised"] is False\n    assert prd101_result["prd2_implementation_authorised"] is False\n\n\ndef test_prd101_snapshot_records_inventory_summary() -> None:\n    snapshot = inventory_snapshot(ROOT)\n    assert snapshot["schema_version"] == "prd1-ci-inventory-authority/v1"\n    assert snapshot["summary"]["workflow_count"] > 0\n    assert snapshot["next_authorised_item"] == "PRD-1.2"\n\n\ndef test_prd101_handoff_target_is_prd1_1_or_prd1_2(prd101_result: dict) -> None:\n    assert prd101_result["next_authorised_item"] in {"PRD-1.1", "PRD-1.2"}\n    if prd101_result["valid"]:\n        assert prd101_result["next_authorised_item"] == "PRD-1.2"\n        assert prd101_result["register_next_authorised_item"] == "PRD-1.2"\n', 'scripts/production_readiness/audit_prd100_ci_release_gate_stream_authority.py': '\n#!/usr/bin/env python3\n"""Audit PRD-1.0 CI/release-gate stream authority and register."""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nfrom pathlib import Path\nfrom typing import Any\n\nfrom scripts.roadmap_reconciliation.verify_prd010_prd0_closure_evidence_handoff import evaluate as evaluate_prd010\n\nPRD_ID = "PRD-1.0"\nSTREAM_ID = "PRD-1-CI-RELEASE-GATE-CONVERGENCE"\nROOT = Path("docs/roadmap/production_readiness")\nREGISTER = ROOT / "production_readiness_register.json"\nPRD1_REGISTER = ROOT / "prd1_ci_release_gate_register.json"\nPRD_DOC = ROOT / "prd_100_ci_release_gate_stream_authority.md"\nPLAN = ROOT / "prd1_ci_release_gate_stream_authority_plan.md"\nSCHEMA_DOC = ROOT / "prd1_ci_release_gate_register.schema.md"\nSEQUENCE_DOC = ROOT / "prd1_ci_release_gate_sequence.md"\nRECORD = ROOT / "prd_100_ci_release_gate_stream_authority_record.json"\nSNAPSHOT = ROOT / "prd1_ci_release_gate_stream_authority.json"\nENGINEERING_DOC = Path("docs/engineering/prd1_ci_release_gate_convergence.md")\n\nTRUE_KEYS = ["runtime_kg_implementation_claimed", "runtime_kg_authority_switch_authorised", "authority_switch_executed"]\nFALSE_KEYS = [\n    "production_release_authorised",\n    "deployment_authorised",\n    "release_tag_authorised",\n    "public_beta_authorised",\n    "public_beta_live_traffic_authorised",\n    "live_learner_traffic_authorised",\n    "billing_launch_authorised",\n    "live_payment_processing_authorised",\n    "new_kg_slice_authorised",\n    "prd2_implementation_authorised",\n]\nNO_CHANGE_KEYS = [\n    "ci_workflow_changes_performed",\n    "required_checks_enforced",\n    "release_gate_enforced",\n    "branch_protection_modified",\n    "workflow_canonicalisation_performed",\n    "openapi_reconciliation_performed",\n]\nEXPECTED_SEQUENCE = [f"PRD-1.{idx}" for idx in range(10)]\n\n\ndef read_json(path: Path) -> dict[str, Any]:\n    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}\n\n\ndef read_text(path: Path) -> str:\n    return path.read_text(encoding="utf-8", errors="replace") if path.exists() else ""\n\n\ndef prd1_sequence_registered(prd1_register: dict[str, Any]) -> bool:\n    sequence = prd1_register.get("prd1_sequence", [])\n    ids = [str(item.get("prd_id")) for item in sequence]\n    return ids == EXPECTED_SEQUENCE\n\n\ndef prd1_0_recorded(prd1_register: dict[str, Any]) -> bool:\n    last_item = str(prd1_register.get("last_recorded_item", ""))\n    next_item = str(prd1_register.get("next_authorised_item", ""))\n    if last_item == PRD_ID and next_item == "PRD-1.1":\n        positioned = True\n    elif last_item.startswith("PRD-1.") and last_item != PRD_ID and next_item.startswith("PRD-1."):\n        positioned = True\n    else:\n        positioned = False\n    if not positioned:\n        return False\n    for item in prd1_register.get("prd1_sequence", []):\n        if item.get("prd_id") == PRD_ID and not (item.get("authorised") is True and item.get("status") == "recorded"):\n            return False\n        if item.get("prd_id") == "PRD-1.1" and not (item.get("authorised") is True and item.get("status") in {"authorised", "next_authorised", "recorded"}):\n            return False\n    return True\n\n\ndef production_register_position(register: dict[str, Any]) -> str:\n    last_item = str(register.get("last_recorded_item", ""))\n    next_item = str(register.get("next_authorised_item", ""))\n    if last_item == "PRD-0.10" and next_item == "PRD-1":\n        return "after_prd0_handoff_before_prd1_capture"\n    if last_item == PRD_ID and next_item == "PRD-1.1":\n        return "prd1_0_recorded"\n    if last_item.startswith("PRD-1.") and last_item != PRD_ID and next_item.startswith("PRD-1."):\n        return "advanced_prd1_subslice"\n    return "unexpected"\n\n\ndef authority_snapshot(root: Path, captured_at: str | None = None) -> dict[str, Any]:\n    register = read_json(root / REGISTER)\n    prd1_register = read_json(root / PRD1_REGISTER)\n    return {\n        "schema_version": "prd1-ci-release-gate-stream-authority/v1",\n        "prd_id": PRD_ID,\n        "stream_id": STREAM_ID,\n        "captured_at": captured_at,\n        "production_readiness_register_summary": {\n            "last_recorded_item": register.get("last_recorded_item"),\n            "next_authorised_item": register.get("next_authorised_item"),\n            "position": production_register_position(register),\n        },\n        "prd1_register_summary": {\n            "last_recorded_item": prd1_register.get("last_recorded_item"),\n            "next_authorised_item": prd1_register.get("next_authorised_item"),\n            "prd1_sequence_registered": prd1_sequence_registered(prd1_register),\n            "prd1_0_recorded": prd1_0_recorded(prd1_register),\n        },\n        "authority_boundaries": {**{key: True for key in TRUE_KEYS}, **{key: False for key in FALSE_KEYS}},\n        "implementation_boundaries": {key: False for key in NO_CHANGE_KEYS},\n        "next_authorised_item": "PRD-1.1" if prd1_0_recorded(prd1_register) else PRD_ID,\n    }\n\n\ndef audit(root: Path = Path(".")) -> dict[str, Any]:\n    errors: list[str] = []\n    warnings: list[str] = []\n    register = read_json(root / REGISTER)\n    prd1_register = read_json(root / PRD1_REGISTER)\n    record = read_json(root / RECORD)\n    snapshot = read_json(root / SNAPSHOT)\n    prd010 = evaluate_prd010(root)\n\n    for path in [PRD_DOC, PLAN, SCHEMA_DOC, SEQUENCE_DOC, RECORD, PRD1_REGISTER, ENGINEERING_DOC]:\n        if not (root / path).exists():\n            errors.append(f"missing required PRD-1.0 file: {path}")\n\n    if prd010.get("valid") is not True:\n        errors.append("PRD-0.10 verifier must remain valid before PRD-1.0")\n    if production_register_position(register) == "unexpected":\n        errors.append("production readiness register must be positioned at PRD-0.10/PRD-1, PRD-1.0/PRD-1.1, or a later PRD-1.x slice")\n    if prd1_register.get("schema_version") != "prd1-ci-release-gate-register/v1":\n        errors.append("PRD-1 register schema_version must be prd1-ci-release-gate-register/v1")\n    if prd1_register.get("stream_id") != STREAM_ID:\n        errors.append("PRD-1 register stream_id must be canonical")\n    if prd1_register.get("parent_stream_id") != "PRD-PRODUCTION-READINESS":\n        errors.append("PRD-1 register parent stream must be PRD-PRODUCTION-READINESS")\n    if prd1_register.get("authorised_by_prd0_10") is not True:\n        errors.append("PRD-1 register must be authorised by PRD-0.10 handoff")\n    if not prd1_sequence_registered(prd1_register):\n        errors.append("PRD-1 register must contain PRD-1.0 through PRD-1.9 sequence")\n\n    required_text = [\n        (read_text(root / PRD_DOC), "PRD-1.1 — CI inventory authority", "PRD-1.0 doc must identify PRD-1.1 as the next slice"),\n        (read_text(root / PRD_DOC), "does not modify CI workflows", "PRD-1.0 doc must preserve no-CI-change boundary"),\n        (read_text(root / PLAN), "last_recorded_item", "PRD-1.0 plan must describe terminal register state"),\n        (read_text(root / SCHEMA_DOC), "prd1-ci-release-gate-register/v1", "PRD-1 schema must define register version"),\n        (read_text(root / SEQUENCE_DOC), "PRD-1.9", "PRD-1 sequence document must include PRD-1.9 handoff"),\n        (read_text(root / ENGINEERING_DOC), "Runtime KG implementation is reserved for PRD-2", "engineering doc must preserve PRD-2 boundary"),\n    ]\n    for text, phrase, message in required_text:\n        if phrase not in text:\n            errors.append(message)\n\n    for key in TRUE_KEYS:\n        if record.get(key) is not True:\n            errors.append(f"{key} must remain true")\n        if prd1_register.get("authority_boundaries", {}).get(key) is not True:\n            errors.append(f"PRD-1 register {key} must remain true")\n    for key in FALSE_KEYS:\n        if record.get(key) is not False:\n            errors.append(f"{key} must remain false")\n        if prd1_register.get("authority_boundaries", {}).get(key) is not False:\n            errors.append(f"PRD-1 register {key} must remain false")\n    for key in NO_CHANGE_KEYS:\n        if record.get(key) is not False:\n            errors.append(f"{key} must remain false in PRD-1.0")\n        if prd1_register.get("implementation_boundaries", {}).get(key) is not False:\n            errors.append(f"PRD-1 register {key} must remain false")\n\n    for key in [\n        "no_ci_workflow_changes_performed",\n        "no_required_check_enforcement_performed",\n        "no_release_gate_enforcement_performed",\n        "no_branch_protection_change_performed",\n        "no_openapi_reconciliation_performed",\n        "no_prd2_implementation_performed",\n    ]:\n        if record.get(key) is not True:\n            errors.append(f"{key} must be true")\n\n    authority_valid = not errors\n    recorded = record.get("prd1_stream_authority_recorded") is True and record.get("prd1_authority_evidence_recorded") is True\n    snapshot_recorded = (\n        snapshot.get("schema_version") == "prd1-ci-release-gate-stream-authority/v1"\n        and snapshot.get("prd_id") == PRD_ID\n        and snapshot.get("prd1_register_summary", {}).get("prd1_sequence_registered") is True\n    )\n    final_valid = (\n        authority_valid\n        and recorded\n        and snapshot_recorded\n        and prd1_0_recorded(prd1_register)\n        and production_register_position(register) in {"prd1_0_recorded", "advanced_prd1_subslice"}\n        and record.get("next_authorised_item") == "PRD-1.1"\n        and record.get("prd1_1_authorised") is True\n    )\n    if authority_valid and not final_valid:\n        warnings.append("PRD-1.0 authority is valid but evidence capture has not completed")\n\n    return {\n        "valid": final_valid,\n        "authority_valid": authority_valid,\n        "prd_id": PRD_ID,\n        "stream_id": STREAM_ID,\n        "errors": errors,\n        "warnings": warnings,\n        "prd010_prd0_closure_evidence_handoff_valid": prd010.get("valid") is True,\n        "prd1_register_created": bool(prd1_register),\n        "prd1_sequence_registered": prd1_sequence_registered(prd1_register),\n        "prd1_stream_authority_recorded": recorded,\n        "prd1_authority_evidence_recorded": record.get("prd1_authority_evidence_recorded") is True,\n        "prd1_0_recorded": prd1_0_recorded(prd1_register),\n        "prd1_1_authorised": record.get("prd1_1_authorised") is True,\n        "next_authorised_item": record.get("next_authorised_item"),\n        "register_next_authorised_item": register.get("next_authorised_item"),\n        "production_register_position": production_register_position(register),\n        "snapshot_recorded": snapshot_recorded,\n        "no_ci_workflow_changes_performed": record.get("no_ci_workflow_changes_performed") is True,\n        "no_required_check_enforcement_performed": record.get("no_required_check_enforcement_performed") is True,\n        "no_release_gate_enforcement_performed": record.get("no_release_gate_enforcement_performed") is True,\n        "no_branch_protection_change_performed": record.get("no_branch_protection_change_performed") is True,\n        "no_openapi_reconciliation_performed": record.get("no_openapi_reconciliation_performed") is True,\n        "no_prd2_implementation_performed": record.get("no_prd2_implementation_performed") is True,\n        **{key: record.get(key) is True for key in TRUE_KEYS},\n        **{key: record.get(key) is True for key in FALSE_KEYS},\n        **{key: record.get(key) is True for key in NO_CHANGE_KEYS},\n    }\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--json", action="store_true")\n    parser.add_argument("--root", default=".")\n    args = parser.parse_args()\n    result = audit(Path(args.root))\n    if args.json:\n        print(json.dumps(result, indent=2, sort_keys=True))\n    else:\n        print(f"PRD-1.0 valid: {result[\'valid\']}")\n        print(f"PRD-1.0 authority_valid: {result[\'authority_valid\']}")\n        for error in result["errors"]:\n            print(f"ERROR: {error}")\n        for warning in result["warnings"]:\n            print(f"WARNING: {warning}")\n    return 0 if result["valid"] else 1\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n', 'tests/unit/roadmap_reconciliation/test_prd100_ci_release_gate_stream_authority.py': '\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport pytest\n\nfrom scripts.production_readiness.audit_prd100_ci_release_gate_stream_authority import authority_snapshot\nfrom scripts.roadmap_reconciliation.verify_prd100_ci_release_gate_stream_authority import evaluate\n\nROOT = Path(__file__).resolve().parents[3]\n\n\n@pytest.fixture(scope="module")\ndef prd100_result() -> dict:\n    return evaluate(ROOT)\n\n\ndef test_prd100_authority_valid_after_apply(prd100_result: dict) -> None:\n    assert prd100_result["authority_valid"] is True\n    assert prd100_result["prd010_prd0_closure_evidence_handoff_valid"] is True\n    assert prd100_result["prd1_register_created"] is True\n    assert prd100_result["prd1_sequence_registered"] is True\n\n\ndef test_prd100_keeps_release_live_and_prd2_boundaries_closed(prd100_result: dict) -> None:\n    assert prd100_result["production_release_authorised"] is False\n    assert prd100_result["deployment_authorised"] is False\n    assert prd100_result["release_tag_authorised"] is False\n    assert prd100_result["public_beta_authorised"] is False\n    assert prd100_result["live_learner_traffic_authorised"] is False\n    assert prd100_result["billing_launch_authorised"] is False\n    assert prd100_result["live_payment_processing_authorised"] is False\n    assert prd100_result["new_kg_slice_authorised"] is False\n    assert prd100_result["prd2_implementation_authorised"] is False\n\n\ndef test_prd100_does_not_perform_ci_or_release_gate_changes(prd100_result: dict) -> None:\n    assert prd100_result["no_ci_workflow_changes_performed"] is True\n    assert prd100_result["no_required_check_enforcement_performed"] is True\n    assert prd100_result["no_release_gate_enforcement_performed"] is True\n    assert prd100_result["no_branch_protection_change_performed"] is True\n    assert prd100_result["no_openapi_reconciliation_performed"] is True\n    assert prd100_result["no_prd2_implementation_performed"] is True\n\n\ndef test_prd100_snapshot_records_prd1_sequence() -> None:\n    snapshot = authority_snapshot(ROOT)\n    assert snapshot["schema_version"] == "prd1-ci-release-gate-stream-authority/v1"\n    assert snapshot["prd_id"] == "PRD-1.0"\n    assert snapshot["stream_id"] == "PRD-1-CI-RELEASE-GATE-CONVERGENCE"\n    assert snapshot["prd1_register_summary"]["prd1_sequence_registered"] is True\n\n\ndef test_prd100_handoff_target_is_prd1_0_or_prd1_1(prd100_result: dict) -> None:\n    assert prd100_result["next_authorised_item"] in {"PRD-1.0", "PRD-1.1"}\n    if prd100_result["valid"]:\n        assert prd100_result["next_authorised_item"] == "PRD-1.1"\n        assert str(prd100_result["register_next_authorised_item"]).startswith("PRD-1.")\n'}
MAKE_BLOCK = '\n# PRD-1.1 CI inventory authority\n.PHONY: prd101-ci-inventory-authority-audit\nprd101-ci-inventory-authority-audit:\n\t$(PYTHON) scripts/production_readiness/audit_prd101_ci_inventory_authority.py --json\n\n.PHONY: prd101-ci-inventory-authority-check\nprd101-ci-inventory-authority-check:\n\t$(PYTHON) -m py_compile scripts/production_readiness/apply_prd101_ci_inventory_authority.py scripts/production_readiness/audit_prd101_ci_inventory_authority.py scripts/roadmap_reconciliation/capture_prd101_ci_inventory_authority_evidence.py scripts/roadmap_reconciliation/verify_prd101_ci_inventory_authority.py\n\tPYTHONPATH=. $(PYTHON) -m pytest -q tests/unit/roadmap_reconciliation/test_prd101_ci_inventory_authority.py --no-cov\n\tPYTHONPATH=. $(PYTHON) scripts/roadmap_reconciliation/verify_prd101_ci_inventory_authority.py --authority-only --json\n\n.PHONY: prd101-ci-inventory-authority-capture\nprd101-ci-inventory-authority-capture:\n\tPYTHONPATH=. $(PYTHON) scripts/roadmap_reconciliation/capture_prd101_ci_inventory_authority_evidence.py --claim-prd101-ci-inventory-authority --prd-owner "$${PRD_OWNER:-Nkgolo Lebelo}" --target-branch "$${TARGET_BRANCH:-master}" --require-valid --json\n# End PRD-1.1 CI inventory authority\n'


def write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def append_makefile(root: Path) -> None:
    makefile = root / "Makefile"
    existing = makefile.read_text(encoding="utf-8") if makefile.exists() else ""
    if "prd101-ci-inventory-authority-audit" not in existing:
        makefile.write_text(existing.rstrip() + "\n" + MAKE_BLOCK + "\n", encoding="utf-8")


def apply(root: Path = Path("."), write_files: bool = True) -> dict:
    if write_files:
        for rel, text in FILES.items():
            write(root / rel, text)
        append_makefile(root)
    return {"prd_id": "PRD-1.1", "applied": bool(write_files), "file_count": len(FILES)}


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("root", nargs="?", default=".")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()
    result = apply(Path(args.root), write_files=True)
    if args.json:
        import json
        print(json.dumps(result, indent=2, sort_keys=True))
    else:
        print(f"Applied {result['prd_id']} authority files ({result['file_count']} files).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
